#!/usr/bin/env python3
"""Curated event timeline. Every entry is drawn from the four documents and carries its references
(fs = Factual Summary paragraph numbers; il = 'person-slug:paragraph'; ex = exhibit ids).
Categories: law (laws & institutions), incident, case (arrests, prosecutions, sentences, measures),
statement (official statements), finding (findings of UN bodies, courts and oversight panels outside Hong Kong)."""
import json, os

E = []
def ev(d, t, x, c, fs=(), il=(), ex=()):
    E.append({'d': d, 't': t, 'x': x, 'c': c if isinstance(c, list) else [c], 'fs': list(fs), 'il': list(il), 'ex': list(ex)})

# ---- constitutional and human-rights framework
ev('1990-04-04', 'Basic Law promulgated', 'The Basic Law of the Hong Kong Special Administrative Region is promulgated, to take effect on 1 July 1997.', 'law', fs=[71, 72, 73], ex=['A3'])
ev('1991-06-08', 'Hong Kong Bill of Rights Ordinance enacted', 'Cap. 383 incorporates the provisions of the International Covenant on Civil and Political Rights as applied to Hong Kong into domestic law.', 'law', fs=[73, 195], ex=['A5'])
ev('1997-07-01', 'Handover: the HKSAR is established', 'British administration ends; Hong Kong becomes a Special Administrative Region of the PRC under “One Country, Two Systems”, retaining a separate common-law system.', 'law', fs=[71, 72])

# ---- 2019
ev('2019-06', 'Mass protests against the extradition bill begin', 'Legislation permitting extradition to mainland China triggers a mass protest movement that develops into broader demands concerning democratic participation, police accountability and civil and political rights.', 'incident', fs=[37, 74], ex=['D2'])
ev('2019-07-21', 'Yuen Long attack', 'Organised groups of armed men attack civilians at and around Yuen Long MTR station; police, despite repeated emergency calls and advance warnings, do not intervene for an extended period and later characterise the events as a clash.', 'incident', fs=[9, 121, 122, 123, 124, 126, 129], ex=['C6', 'C7', 'C8', 'C9', 'C10', 'C11'])
ev('2019-07-29', 'Police association chairman: “cockroaches”, “not human”', 'Lam Chi-wai, chairman of the Junior Police Officers’ Association, describes those who vandalised the graves of a pro-Beijing legislator’s parents as “low lives”, “cockroaches” and “not human”.', 'statement', fs=[154], ex=['D4'])
ev('2019-08-11', 'Arrested persons taken to San Uk Ling', 'At least 54 arrested persons are transported to the San Uk Ling holding centre, close to the boundary with mainland China and far from the principal protest locations.', 'incident', fs=[90, 91, 92, 93, 94, 95, 96, 97, 98, 99])
ev('2019-08-17', 'Xinhua cartoon depicts protesters as cockroaches', 'State media amplifies the language of vermin with a political cartoon portraying pro-democracy protesters as cockroaches.', 'statement', fs=[155, 156], ex=['D5'])
ev('2019-08-18', 'Peaceful procession of an estimated 1.7 million people', 'A procession from Victoria Park, which organisers estimated drew 1.7 million people, later becomes the basis of convictions for organising and taking part in an unauthorised assembly.', 'incident', il=['amanda-jane-woodcock:3.2.1', 'roberto-alexandre-vieira-ribeiro:3.2.1'], ex=['G5'])
ev('2019-10-01', 'Student shot in the chest with a live round', 'A police officer shoots a secondary-school student in the chest with a live round, drawing widespread criticism of the police as “trigger-happy”; no officer is prosecuted. Ten pro-democracy figures are later sentenced to terms of up to 18 months’ imprisonment over the unauthorised assembly of the same day.', 'incident', fs=[131, 132], il=['amanda-jane-woodcock:3.3.1'], ex=['C3'])
ev('2019-10-06', 'Taxi driven into a crowd of protesters', 'A taxi driver is alleged deliberately to have driven into a crowd of protesters; a magistrate later finds sufficient grounds for a private prosecution for dangerous driving.', 'incident', fs=[135], ex=['C21', 'C22'])
ev('2019-10-22', '“Ms X” files a criminal complaint of rape in custody', 'An 18-year-old woman, through her lawyers, lodges a criminal complaint alleging that she was raped by multiple police officers during her detention.', 'case', fs=[78, 79, 80, 81], ex=['C23'])
ev('2019-10-26', 'Police deny receiving sexual-assault complaints at San Uk Ling', 'A police spokesperson states that no complaint of sexual assault at San Uk Ling had been received and declines to disclose whether complaints concerning Tsuen Wan Police Station were under investigation.', 'statement', fs=[110])
ev('2019-11-08', 'International Expert Panel: IPCC powers fall significantly short', 'The five-member panel appointed to advise the Independent Police Complaints Council issues a position statement finding a significant shortfall in the IPCC’s powers, capacity and independent investigative capability.', 'finding', fs=[102, 103, 104], ex=['C29'])
ev('2019-11-11', 'Unarmed protester shot at close range', 'An on-duty police officer shoots an unarmed protester at close range; a magistrate later finds sufficient grounds to issue summonses for shooting with intent, but the private prosecution is terminated by the Department of Justice.', 'incident', fs=[134, 136], il=['lee-wan-tang-alex:3.3.1'], ex=['C20'])
ev('2019-11-16', 'Police call Ms X’s complaint “fake information”', 'The police publicly state that her complaint contained “fake information” and indicate that they will investigate whether she made a false report.', 'statement', fs=[84], ex=['C23'])
ev('2019-12-09', 'Six months of protest: 16,000 tear-gas rounds, 2,600 hospital attendances', 'The authorities acknowledge approximately 16,000 discharges of tear gas, 13,900 rounds of ammunition of various kinds and 2,600 persons treated at public-hospital emergency departments.', 'incident', fs=[5, 75, 76], ex=['C1'])
ev('2019-12-11', 'International Expert Panel withdraws from the IPCC review', 'The panel announces that the deficiencies in the IPCC’s powers, capacity and independence prevent it from meeting the standards expected of a police watchdog, and withdraws.', 'finding', fs=[108, 109], ex=['C30'])

# ---- 2020
ev('2020-05-12', 'Ms X declared wanted for “making a false statement”', 'With the Police Force under the command of Commissioner Chris Tang, police announce that the complainant who alleged rape by officers is herself wanted; no officer is prosecuted for the alleged rape.', ['case', 'statement'], fs=[86, 87, 88], il=['chris-tang-ping-keung:4.2'], ex=['C23', 'C25'])
ev('2020-06-30', 'Hong Kong National Security Law enters into force', 'The Law of the PRC on Safeguarding National Security in the HKSAR is promulgated and enters into force, creating offences of secession, subversion, terrorism and collusion, a reverse presumption against bail (Article 42(2)) and designated national-security judges (Article 44).', 'law', fs=[1, 37, 114, 146, 189, 190], ex=['A7'])
ev('2020-07-01', 'National Security Department of the police established', 'The National Security Department of the Hong Kong Police Force is established pursuant to Articles 16 and 17 of the HKNSL.', 'law', fs=[141])
ev('2020-07-07', 'Implementation Rules for Article 43 of the HKNSL', 'The Rules confer additional enforcement powers in national-security investigations, including compulsory information notices.', 'law', fs=[197], ex=['A11'])
ev('2020-07-08', 'Office for Safeguarding National Security established', 'The Office for Safeguarding National Security of the Central People’s Government in the HKSAR is established.', 'law', fs=[142])
ev('2020-07', 'Pro-democracy primary election', '47 pro-democracy politicians and activists organise or participate in an unofficial primary to coordinate candidates for the Legislative Council election; the authorities later characterise the strategy as a conspiracy to commit subversion.', 'case', fs=[241, 242, 243, 244], ex=['E12'])
ev('2020-08-24', 'Secretary for Justice withdraws Ted Hui’s private prosecutions', 'The Secretary for Justice takes over and withdraws both private prosecutions concerning the 11 November 2019 shooting and the 6 October 2019 taxi incident.', 'case', fs=[133, 136, 138], il=['lee-wan-tang-alex:3.3.1', 'lee-wan-tang-alex:3.3.2'], ex=['C20', 'C21', 'C22'])
ev('2020-12', 'Jimmy Lai detained', 'The founder of Apple Daily, a British citizen, is taken into custody; he remains detained until his conviction in December 2025.', 'case', fs=[226, 227], il=['roberto-alexandre-vieira-ribeiro:3.1.3'], ex=['E9'])

# ---- 2021
ev('2021-02-09', 'Court of Final Appeal reverses Jimmy Lai’s bail', 'A five-judge panel allows the prosecution’s appeal, holding that Article 42(2) of the HKNSL creates a specific exception to the ordinary rules governing bail; the ruling becomes the framework under which bail is refused in most national-security prosecutions.', 'case', fs=[189, 190, 191, 192], il=['roberto-alexandre-vieira-ribeiro:3.1.1', 'roberto-alexandre-vieira-ribeiro:3.1.2', 'joseph-paul-fok:3.1.1', 'frank-stock:3.1.1', 'patrick-chan-siu-oi:3.1.1'], ex=['G2', 'G4'])
ev('2021-04-01', '18 August 2019 procession: seven convicted', 'Judge Woodcock convicts Jimmy Lai, Martin Lee, Margaret Ng, Lee Cheuk-yan, Albert Ho, Leung Kwok-hung and Cyd Ho of organising and knowingly taking part in an unauthorised assembly.', 'case', il=['amanda-jane-woodcock:3.2.1'], ex=['G5'])
ev('2021-04-26', 'Sedition ruling in Tam Tak-chi: no intent to incite violence required', 'Judge Stanley Chan holds that an intention to incite violence is not an essential element of uttering seditious words under the revived colonial-era provisions, which had not been used for decades.', 'case', fs=[115], il=['chan-kwong-chi-stanley:3.1.1'], ex=['A6', 'G17'])
ev('2021-05-07', 'Judicial review of the terminated private prosecutions refused', 'Judge Alex Lee refuses Ted Hui leave to apply for judicial review of the Secretary for Justice’s interventions and orders indemnity costs.', 'case', fs=[133, 136], il=['lee-wan-tang-alex:3.3.1', 'lee-wan-tang-alex:3.3.2'])
ev('2021-05-28', '1 October 2019 assembly: sentences of up to 18 months', 'Judge Woodcock sentences ten pro-democracy figures, including Figo Chan, Lee Cheuk-yan, Leung Kwok-hung, Albert Ho and Jimmy Lai, for their part in an unauthorised assembly.', 'case', il=['amanda-jane-woodcock:3.3.1'], ex=['G13'])
ev('2021-06-23', 'Apple Daily announces closure', 'The pro-democracy newspaper announces its closure after the authorities freeze its assets under the HKNSL.', 'incident', ex=['G3'])
ev('2021-07-31', 'Liaison Office: teachers’ union a “poisonous tumour”', 'The Liaison Office republishes a Xinhua commentary describing the Professional Teachers’ Union as a “poisonous tumour” and pro-democracy organisations as “scattering like monkeys when the tree falls”.', 'statement', fs=[158], ex=['D6'])
ev('2021-08-10', 'Professional Teachers’ Union disbands', 'Hong Kong’s largest teachers’ union disbands after sustained public attacks and political pressure from the authorities.', 'incident', fs=[159], ex=['D7'])
ev('2021-10-25', 'Ma Chun-man convicted of inciting secession for chanting slogans', 'Judge Stanley Chan convicts Ma of inciting secession for slogans and speeches on at least 20 occasions, without any advocacy of violence; on 11 November 2021 he is sentenced to five years and nine months.', 'case', il=['chan-kwong-chi-stanley:3.2.1'], ex=['G19', 'G20'])
ev('2021-11-23', 'Tony Chung, 20, sentenced under the HKNSL', 'Tony Chung is sentenced to three years and seven months’ imprisonment for “secession” on the basis of social-media posts; he had been arrested at the age of 19.', 'case', fs=[339], ex=['E2'])
ev('2021-12-09', 'Tang: legal cooperation “temporarily suspended”; exiles “sought protection from foreign countries”', 'In an interview the Secretary for Security says that ordinary channels of inter-State legal cooperation have been suspended for political reasons and that the only beneficiaries are wanted persons who have sought protection abroad.', 'statement', fs=[13, 378], il=['chris-tang-ping-keung:4.4'], ex=['F17'])
ev('2021-12-23', '“Pillar of Shame” removed from the University of Hong Kong', 'The sculpture commemorating those killed in 1989, displayed at HKU since June 1997, is removed despite the artist’s offer to retrieve it.', 'incident', fs=[280, 281], ex=['E21'])

# ---- 2022
ev('2022-03-02', 'Tam Tak-chi convicted; 40 months’ imprisonment', 'Judge Stanley Chan convicts Tam of 11 of 14 charges, including seven counts of uttering seditious words, and on 20 April 2022 sentences him to a total of 40 months.', 'case', il=['chan-kwong-chi-stanley:3.1.1', 'chan-kwong-chi-stanley:3.1.2'], ex=['G17', 'G18'])
ev('2022-04-29', 'Lui Sai-yu sentenced to five years for Telegram posts', 'Judge Woodcock sentences the university student to five years’ imprisonment for inciting secession, following his guilty plea to posting pro-independence messages.', 'case', il=['amanda-jane-woodcock:3.1.1'], ex=['G12'])
ev('2022', 'First minors convicted under the HKNSL', 'Four persons aged 16 and 17 become the first minors convicted under the national security law.', 'case', fs=[316, 317], ex=['C33'])
ev('2022-07-12', 'Koo Sze-yiu, 75 and terminally ill, jailed for a planned protest', 'Principal Magistrate Law convicts the veteran activist of attempting to commit a seditious act — planning to carry a mock coffin to the Liaison Office — and sentences him to nine months.', 'case', fs=[286, 287, 288], il=['law-tak-chuen-peter:3.3.1'], ex=['E23'])
ev('2022-07-27', 'Government “strongly objects” to UN Human Rights Committee', 'Responding to the Committee’s concluding observations under the ICCPR, the Government characterises the criticism as unfair and unfounded.', 'statement', fs=[460], ex=['D15'])
ev('2022-09-07', 'Speech therapists convicted over children’s books', 'Judge Kwok convicts five speech therapists of conspiracy to publish seditious publications in respect of three illustrated books about sheep and wolves; on 10 September 2022 each is sentenced to 19 months.', 'case', fs=[269, 270, 271, 272], il=['kwok-wai-kin:3.1.1'], ex=['E1', 'E18'])
ev('2022-10-22', '“Student Politicism” members jailed for up to 36 months', 'Judge Kwok sentences four members of the student group, who had operated street booths and chanted slogans, for conspiracy to incite subversion; the youngest is sent to a training centre.', 'case', il=['kwok-wai-kin:3.2.1'], ex=['G14'])
ev('2022-10-25', 'Luk Ting-fung: six months for online forum posts', 'Chief Magistrate So sentences the former civil servant for publishing seditious publications consisting of posts and comments on the LIHKG forum.', 'case', il=['so-wai-tak-victor:3.1.1'], ex=['G24'])
ev('2022-10-27', 'Pastor convicted of sedition for clapping in court', 'Garry Pang Moon-yuen is convicted following conduct that included clapping in court in support of defendants prosecuted over the prohibited 4 June vigil.', 'case', fs=[278, 279], ex=['E20'])

# ---- 2023
ev('2023-03-04', 'Alliance members convicted for refusing a police information notice', 'Principal Magistrate Law convicts Chow Hang-tung, Tang Ngok-kwan and Tsui Hon-kwong, holding that the prosecution need not prove the Alliance was a “foreign agent”; on 11 March 2023 each is sentenced to four and a half months as a “punitive and sufficiently deterrent” measure.', 'case', fs=[254, 255, 256], il=['law-tak-chuen-peter:3.1.1', 'law-tak-chuen-peter:3.1.2'], ex=['E15', 'E16'])
ev('2023-05-01', 'UN Working Group: Chow Hang-tung’s detention is arbitrary', 'The Working Group on Arbitrary Detention finds that Chow Hang-tung was arbitrarily deprived of her liberty and calls for her release and compensation.', 'finding', fs=[310, 311, 313], ex=['B4'])
ev('2023-07-03', 'Arrest warrants and HK$1 million bounties for eight overseas activists', 'The National Security Department announces warrants against eight persons who had left Hong Kong, three of them resident in the United Kingdom, and invites information “in Hong Kong or overseas”.', 'case', fs=[11, 13, 367, 369, 376], ex=['F1'])
ev('2023-07-04', 'John Lee: pursued “for life”, living “in fear every day”', 'The Chief Executive endorses the bounties, says the wanted persons will be pursued for life no matter where they flee, invites their relatives and friends to inform for reward, and asserts that Hong Kong’s law has “the same power of taking extraterritorial action” as other States’ laws.', 'statement', fs=[12, 371, 372, 394, 567], il=['john-lee-ka-chiu:4.4'], ex=['F5', 'F6', 'F7', 'F18', 'F19'])
ev('2023-07-04', 'Chris Tang: identify their “contacts, associates and financiers … in Hong Kong or overseas”', 'The Secretary for Security says the authorities will “devote their whole lives” to bringing the wanted persons back and describes Nathan Law as a “modern-day traitor of the Chinese nation”.', 'statement', fs=[12, 373, 374, 572], il=['chris-tang-ping-keung:4.4'], ex=['F8', 'F9', 'F10'])
ev('2023-07-11', 'John Lee: the pursuit “will be lifelong”; treat them as “rats crossing the street”', 'The Chief Executive says anyone providing financial or other assistance, or “backing”, will be held accountable, and that the public should shun the wanted persons as “rats crossing the street”.', 'statement', fs=[12, 375], il=['john-lee-ka-chiu:4.4'], ex=['F11', 'F12'])
ev('2023-07-11', 'Nathan Law’s family taken in for questioning', 'Members of the exiled activist’s family are taken in for questioning by Hong Kong police, a week after the bounty announcement.', 'incident', fs=[395, 396], ex=['F23'])
ev('2023-07-20', 'Homes of relatives of two exiled activists searched', 'Police search the homes of relatives of two exiled activists.', 'incident', fs=[397], ex=['F24'])
ev('2023-08-22', 'Court of Final Appeal: HKNSL sentencing bands are mandatory', 'Dismissing Lui Sai-yu’s appeal, the Court holds that the sentencing bands in Article 21 are mandatory and that only the circumstances in Article 33 permit a sentence below the prescribed minimum.', 'case', il=['roberto-alexandre-vieira-ribeiro:3.4.1', 'roberto-alexandre-vieira-ribeiro:3.4.2', 'patrick-chan-siu-oi:3.2.1', 'amanda-jane-woodcock:3.1.2'], ex=['G7'])
ev('2023-08-27', 'Tang: “people must under no circumstances contact them”', 'Asked about a United States statement that the National Security Department had harassed the families of the eight wanted persons, the Secretary for Security does not deny it and accuses the United States of trying to “demonise” Hong Kong’s actions.', 'statement', fs=[375, 401], il=['chris-tang-ping-keung:4.4'], ex=['F13'])
ev('2023-09-12', 'Zeng Yuxuan jailed for a banner that was never displayed', 'Principal Magistrate Law sentences the mainland law student to six months for planning to display a “Pillar of Shame” banner; she is later deported to mainland China.', 'case', fs=[282, 283, 284, 285], il=['law-tak-chuen-peter:3.2.1'], ex=['E22'])
ev('2023-11-03', 'Yuen Ching-ting jailed for posts made while studying in Japan', 'Chief Magistrate So sentences the 23-year-old student to two months for 13 Facebook and Instagram posts, most made abroad, which the authorities accepted were slogans that generated no heated discussion.', 'case', fs=[273, 274, 275, 276, 277], il=['so-wai-tak-victor:3.2.1'], ex=['E19'])
ev('2023-12-13', 'Four arrested for crowdfunding support to wanted persons', 'Four persons in Hong Kong, aged 29 to 68, are arrested on suspicion of providing pecuniary assistance through online crowdfunding to two wanted persons overseas.', 'case', fs=[368], ex=['F2'])
ev('2023-12-14', 'Bounties on five more overseas activists', 'Rewards of HK$1,000,000 are announced in respect of five further persons, including Simon Cheng, Fok Ka-chi and Choi Ming-da.', 'case', fs=[368], ex=['F2'])
ev('2023-12-15', 'Tang: “unable to see the light like a rat crossing the street”', 'The Secretary for Security tells the newly wanted persons that “no matter how long you wait, you remain a wanted person”, that a foreign power will discard them “once you lose your use value”, and that they will “bring shame upon your family”.', 'statement', fs=[165, 374], il=['chris-tang-ping-keung:4.4'], ex=['F14'])
ev('2023-12-29', 'Tony Chung flees to the United Kingdom', 'Released in June 2023 under conditions prohibiting public statements about his conviction, required to attend recurring national-security police meetings and, by his account, offered payment to inform, Chung leaves Hong Kong.', 'incident', fs=[339, 340, 341, 342, 343], ex=['E24', 'E25'])

# ---- 2024
ev('2024-01-25', 'Court of Final Appeal upholds Chow Hang-tung’s vigil conviction', 'Justice Ribeiro, delivering the leading judgment, reinstates the conviction for inciting others to take part in an unauthorised assembly by calling on the public to commemorate 4 June.', 'case', il=['roberto-alexandre-vieira-ribeiro:3.3.1', 'roberto-alexandre-vieira-ribeiro:3.3.2', 'joseph-paul-fok:3.3.1'], ex=['G6'])
ev('2024-01-31', 'UN Special Rapporteur on torture addresses the Jimmy Lai trial', 'The Special Rapporteur publicly addresses allegations that evidence from a key prosecution witness in the Lai proceedings was obtained through torture.', 'finding', fs=[438, 439], ex=['B5'])
ev('2024-03-12', 'Legislator: national-security offenders “worse than murderers or arsonists”', 'During consideration of the Article 23 legislation, Legislative Council committee vice-chairman Chan Hak-kan describes persons endangering national security in these terms.', 'statement', fs=[160], ex=['D8'])
ev('2024-03-23', 'Safeguarding National Security Ordinance (Article 23) in force', 'The Ordinance expands sedition, adds extended detention and investigative powers (sections 76–78) and restrictions on access to a chosen lawyer, creates “specified absconder” measures (section 89) and restricts early release for national-security prisoners.', 'law', fs=[37, 118, 185, 201, 347, 348, 383, 384, 464], ex=['A9', 'D1'])
ev('2024-03-26', 'First use of the Ordinance against prisoners: no early release', 'National-security prisoners are no longer eligible for the standard one-third remission for good behaviour unless they satisfy the national-security standard; the rule applies to persons sentenced before the Ordinance.', 'case', fs=[347, 348, 349, 350], ex=['E26'])
ev('2024-05-13', 'Three men charged in the United Kingdom', 'Chung Biu (Bill) Yuen, Chi Leung (Peter) Wai and Matthew Trickett are charged with assisting a Hong Kong intelligence service and foreign-interference activity directed at persons within the United Kingdom.', 'case', fs=[405, 406, 407, 408], ex=['F28'])
ev('2024-05-14', 'John Lee: the UK’s “fabrication”', 'Responding to the charging of the HKETO office manager, the Chief Executive states that “the Chinese side firmly rejects and strongly condemns the UK’s fabrication”.', 'statement', fs=[415], il=['john-lee-ka-chiu:4.4'], ex=['F33'])
ev('2024-05-19', 'Regina Ip: HKETO must “monitor” exiled Hongkongers', 'The Convenor of the Executive Council says the role of the Hong Kong Economic and Trade Office in London has “changed” and that it needs to monitor the activities of exiled Hongkongers.', 'statement', fs=[416], ex=['F34'])
ev('2024-05-30', 'Hong Kong 47: 14 of 16 contesting defendants convicted', 'A three-judge national-security panel convicts the defendants of conspiracy to commit subversion for the July 2020 primary; 45 defendants are convicted in total.', 'case', fs=[245, 246, 247, 248], il=['chan-hing-wai-andrew:3.1.2', 'lee-wan-tang-alex:3.1.2', 'chan-jong-herng-johnny:3.1.2'], ex=['E12'])
ev('2024-06-07', 'Three arrested for not standing during the national anthem', 'Three persons are arrested at a World Cup qualifying match for failing to stand while the Chinese national anthem is played.', 'case', fs=[116], ex=['E4'])
ev('2024-06-11', 'Government “strongly disagrees” with Lord Sumption', 'After the Non-Permanent Judge resigns saying Hong Kong is “becoming a totalitarian state”, the Government publicly rejects and condemns his criticisms.', 'statement', fs=[213, 214], ex=['D10', 'D11'])
ev('2024-06-12', 'First six “specified absconders”: Tang says they are “hiding in the United Kingdom”', 'The Secretary for Security specifies Nathan Law, Christopher Mung, Finn Lau, Simon Cheng, Fok Ka-chi and Choi Ming-da under section 89: passports cancelled, funding prohibited “no matter what platform it is”, including for BN(O) subscribers in the UK.', ['case', 'statement'], fs=[386, 388, 389, 390, 391], il=['chris-tang-ping-keung:4.5'], ex=['F20', 'F21'])
ev('2024-08-12', 'Court of Final Appeal dismisses the 18 August 2019 appeals', 'The Court unanimously dismisses the final appeals of seven pro-democracy figures, declining to follow the UK Supreme Court’s “operational proportionality” approach in DPP v Ziegler.', 'case', il=['roberto-alexandre-vieira-ribeiro:3.2.1', 'roberto-alexandre-vieira-ribeiro:3.2.2', 'joseph-paul-fok:3.2.1'], ex=['G5'])
ev('2024-08-29', 'Stand News editors convicted of seditious publication', 'Judge Kwok convicts Chung Pui-kuen and Patrick Lam, finding 11 of 17 articles seditious and holding that no intent to incite violence or even disaffection need be proved; on 26 September 2024 they are sentenced to 21 and 11 months.', 'case', fs=[263, 264, 265, 266], il=['kwok-wai-kin:3.3.1', 'kwok-wai-kin:3.3.3'], ex=['E17', 'G15'])
ev('2024-09-19', 'First sedition sentence under the Ordinance: 14 months for a T-shirt', 'Chief Magistrate So sentences Chu Kai-pong for wearing a T-shirt bearing “Liberate Hong Kong, revolution of our times”; the same day Chung Man-kit receives ten months for slogans on bus seats, and on 20 September Au Kin-wai, 58, receives 14 months for social-media posts.', 'case', il=['so-wai-tak-victor:3.3.1', 'so-wai-tak-victor:3.4.1', 'so-wai-tak-victor:3.5.1'], ex=['G25', 'G26', 'G27'])
ev('2024-09-26', 'UN Working Group: Jimmy Lai’s detention is arbitrary', 'The Working Group on Arbitrary Detention finds Lai’s detention arbitrary and records that by September 2024 he had spent more than three and a half years in solitary confinement.', 'finding', fs=[312, 436, 440], ex=['B5'])
ev('2024-11-19', 'Hong Kong 47 sentenced to between 4 years 2 months and 10 years', 'The panel sentences all 45 convicted defendants, many of whom had already spent lengthy periods in pre-trial detention under the national-security bail regime.', 'case', fs=[245, 246], il=['chan-hing-wai-andrew:3.1.3', 'lee-wan-tang-alex:3.1.3', 'chan-jong-herng-johnny:3.1.3'], ex=['E3'])
ev('2024-12-24', 'Bounties on six more; Tang: “no person … can evade criminal responsibility” by being overseas', 'Warrants and HK$1,000,000 rewards are announced against Carmen Lau, Tony Chung, Chung Kim-wah, Chloe Cheung and two others; the Secretary for Security says the Government “will use every means” against those “unrepentant” in endangering national security.', ['case', 'statement'], fs=[368, 374], ex=['F3', 'F15'])

# ---- 2025
ev('2025-02-24', 'Lai trial: “no political statements” from the witness box', 'While giving evidence, Jimmy Lai is repeatedly interrupted by the presiding judges, at times confined to answering “agree” or “disagree”, and told that political statements will not be allowed.', 'case', fs=[230, 231], ex=['E6'])
ev('2025-05', 'Li Chun-kit: one year for Facebook posts', 'Chief Magistrate So sentences the former bus technician for posts found to incite hatred against the police, the judiciary and the Government.', 'case', il=['so-wai-tak-victor:3.6.1'], ex=['G28'])
ev('2025-05-02', 'Family member of an overseas activist arrested', 'Hong Kong police arrest a family member of a pro-democracy activist living abroad.', 'incident', fs=[398], ex=['F25'])
ev('2025-06-22', 'Secretary for Justice: national-security conviction rate above 95 per cent', 'Paul Lam says the rate reflects well-founded prosecutions and accuses “forces” of smearing the system.', 'statement', fs=[169, 170], ex=['C12'])
